    'url-lookalike': {'title':'Domínio com grafia semelhante','signal':'Um domínio substitui, acrescenta ou remove caracteres para se parecer com uma organização conhecida.','meaning':'Pequenas diferenças ortográficas, palavras adicionais ou caracteres trocados podem fazer um domínio controlado por um atacante parecer familiar.','action':'Compare, carácter a carácter, o domínio registável completo com um endereço obtido de forma independente.','limit':'Um nome semelhante é motivo para verificar, não prova de propriedade maliciosa.'},
